import React, { useEffect, useState } from 'react';
import './App.css';

function App() {
  const [movies, setMovies] = useState([]);
  const [selectedMovie, setSelectedMovie] = useState(null);

  useEffect(() => {
    fetch('/api/movies')
      .then(res => res.json())
      .then(data => {
        console.log("Fetched movies:", data);
        if (Array.isArray(data)) {
          setMovies(data);
        } else if (data.movies) {
          setMovies(data.movies);
        } else {
          console.error("Unexpected data format:", data);
        }
      })
      .catch(err => console.error("Error fetching movies:", err));
  }, []);

  if (selectedMovie) {
    return (
      <div className="movie-detail">
        <h2>{selectedMovie.title}</h2>
        <p>{selectedMovie.tagline || "No tagline"}</p>
        <p>{selectedMovie.overview}</p>
        <p>Release Date: {selectedMovie.release_date}</p>
        <p>Runtime: {selectedMovie.runtime} minutes</p>
        <p>⭐ {selectedMovie.vote_average}/10</p>
        <button onClick={() => setSelectedMovie(null)}>Back to list</button>
      </div>
    );
  }

  return (
    <div className="movie-list">
      {movies.length === 0 ? (
        <p>No movies loaded</p>
      ) : (
        movies.map(m => (
          <div
            key={m.id}
            className="movie-card"
            onClick={() => setSelectedMovie(m)}
          >
            <h3>{m.title}</h3>
            <p>{m.tagline || "No tagline"}</p>
            <p>⭐ {m.vote_average}/10</p>
          </div>
        ))
      )}
    </div>
  );
}

export default App;
